/**
 * TimezoneInfo is a representation of the timezone.
 * It can be a standard IANA timezone, or a customized timezone with label and a fixed utcOffset.
 */
export type TimezoneInfo = {
    helpContent?: string;
    /** The customized human readable label display of the timezone, e.g. `'Los Angeles Time'` */
    label?: string;
} & ({
    /** The standard IANA timezone id, e.g. `'Asia/Hong_Kong'` */
    id: string;
    /** Standard IANA timezone id is not allowed to have a fixed utcOffset */
    utcOffset?: never;
} | {
    /** The customized timezone should not have a timezone id, to distinguish it from the standard IANA timezone id. */
    id?: never;
    /** The customized fixed utcOffset of the timezone, in minutes, e.g. `-480` */
    utcOffset: number;
});
/**
 * Represents the timezone for date-time operations. `'UTC'`, `'local'`,
 * or `TimezoneInfo` (a standard IANA timezone, or a customized timezone with label and a fixed utcOffset).
 */
export type Timezone = 'local' | 'UTC' | TimezoneInfo;
